#ifndef ACMOTION_JOINT_TRAJECTORY_HPP
#define ACMOTION_JOINT_TRAJECTORY_HPP

#include <cstdint>

namespace ac::motion {

/**
 * @struct JointTarget
 * @brief One SCARA joint-space target generated by inverse kinematics on the SBC.
 *
 * Units are explicit:
 * - joint1Rad, joint2Rad and joint3Rad are radians;
 * - zMm is millimetres;
 * - gripperPercent is in [0, 100].
 *
 * This structure is intentionally free of chess-domain semantics so it can be
 * serialized toward the ESP32-S3 without exposing FEN, PieceType or Square.
 *
 * J3 represents the distal/end-effector rotational axis present on the
 * selected How To Mechatronics SCARA.
 */
struct JointTarget {
    double joint1Rad{0.0};      ///< First revolute SCARA joint angle in radians.
    double joint2Rad{0.0};      ///< Second revolute SCARA joint angle in radians.
    double joint3Rad{0.0};      ///< Distal/tool revolute joint angle in radians.
    double zMm{0.0};            ///< Linear Z-axis target in millimetres.
    double gripperPercent{0.0}; ///< Gripper aperture percentage in [0, 100].
};

/**
 * @struct JointSegment
 * @brief Version-independent joint-space segment scheduled for the ESP32-S3.
 */
struct JointSegment {
    std::uint32_t sequence{0};  ///< Monotonic non-zero sequence identifier.
    JointTarget target{};       ///< Joint-space endpoint.
    std::uint32_t durationMs{0};///< Requested segment duration in milliseconds.
};

} // namespace ac::motion

#endif
